use crate::resample::down_up_rgb8;
use crate::types::FoveationConfig;
#[inline] fn lerp_u8(a:u8,b:u8,t:f32)->u8{(a as f32+(b as f32-a as f32)*t.clamp(0.0,1.0)).round().clamp(0.0,255.0) as u8}
pub fn foveate_rgb8_with_map(src:&[u8],width:usize,height:usize,quality:&[f32],cfg:&FoveationConfig)->Vec<u8>{if src.len()<width*height*3||quality.len()<width*height||width==0||height==0{return Vec::new();}let s0=cfg.peripheral_scale.clamp(0.03125,1.0);let s1=s0.sqrt().clamp(s0,1.0);let s2=s1.sqrt().clamp(s1,1.0);let low0=down_up_rgb8(src,width,height,s0);let low1=down_up_rgb8(src,width,height,s1);let low2=down_up_rgb8(src,width,height,s2);let mut out=vec![0u8;width*height*3];for i in 0..width*height{let q=quality[i].clamp(0.0,1.0);let level=q*3.0;let base=level.floor() as i32;let frac=level-base as f32;for c in 0..3{let idx=i*3+c;let a=match base{0=>low0[idx],1=>low1[idx],2=>low2[idx],_=>src[idx]};let b=match base{0=>low1[idx],1=>low2[idx],2=>src[idx],_=>src[idx]};out[idx]=lerp_u8(a,b,frac);}if cfg.peripheral_desaturate>0.0{let d=((1.0-q)*cfg.peripheral_desaturate).clamp(0.0,1.0);let r=out[i*3] as f32;let g=out[i*3+1] as f32;let b=out[i*3+2] as f32;let y=0.2126*r+0.7152*g+0.0722*b;out[i*3]=(r+(y-r)*d).round().clamp(0.0,255.0) as u8;out[i*3+1]=(g+(y-g)*d).round().clamp(0.0,255.0) as u8;out[i*3+2]=(b+(y-b)*d).round().clamp(0.0,255.0) as u8;}}out}
